import{FIGHT}from"./react-fight.js";import{BOSS}from"./react-boss.js";import{WORLD}from"./react-world.js";const HANDLERS={...FIGHT,...BOSS,...WORLD};export function applyEvent(fx,ev,rng,world){Object.hasOwn(HANDLERS,ev.type)&&HANDLERS[ev.type](fx,ev,rng,world)}export function applyEvents(fx,events,rng,world){for(const ev of events)applyEvent(fx,ev,rng,world)}
